    for prof in Professeur.objects.select_related('utilisateur'):
        if not prof.utilisateur_id:
            continue
        champs = []
        if not prof.email and prof.utilisateur.email:
            prof.email = prof.utilisateur.email
            champs.append('email')
        if not prof.telephone and prof.utilisateur.telephone:
            prof.telephone = prof.utilisateur.telephone
            champs.append('telephone')
        if champs:
            prof.save(update_fields=champs)


